## Code Example
```javascript
// Pseudo-beam sketch (JavaScript/TypeScript syntax used for illustration)
class ParseEvent extends DoFn {
  @ProcessElement
  process(@Element json, output) {
    const event = JSON.parse(json.image);
    this.ingested.inc();
    // ... validation and transformation
    this.processed.inc();
    output(event);
  }

  @Setup
  setup() {
    this.ingested = Metrics.counter('pipeline', 'ingested_events');
    this.processed = Metrics.counter('pipeline', 'processed_events');
    this.failed = Metrics.counter('pipeline', 'failed_events');
  }
}
```

